-- =====================================================================
--  Réparation de la vue `v_moteur_alertes`
--
--  L'export phpMyAdmin (gestion_personnel.sql) génère pour cette vue des
--  alias de colonnes auto-générés à partir du texte de l'expression.
--  46 d'entre eux dépassent la limite de 64 caractères d'un identifiant
--  MySQL, ce qui fait échouer la création de la vue :
--      ERROR 1166 (42000): Incorrect column name 'DATE_ADD(pc.date_...'
--  La vue est alors absente et toutes les pages qui l'interrogent
--  (dossiers_en_cours, liste_demandes_dos, dashboard_responsable, ...)
--  tombent en Fatal error.
--
--  Ce script rejoue la même définition avec des alias internes courts et
--  fige explicitement les 9 noms de colonnes publics de la vue, tels que
--  déclarés par le dump lui-même (« Doublure de structure »).
--
--  Second défaut corrigé ici : la CTE `progression_carriere` se référence
--  elle-même (UNION ALL) mais l'export l'écrit « WITH » au lieu de
--  « WITH RECURSIVE », ce qui provoque :
--      ERROR 1146: Table 'progression_carriere' doesn't exist
-- =====================================================================

-- La vue contient des COLLATE utf8mb4_* : la connexion doit être en utf8mb4.
SET NAMES utf8mb4;

DROP VIEW IF EXISTS `v_moteur_alertes`;
DROP TABLE IF EXISTS `v_moteur_alertes`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_moteur_alertes` (`alerte_id`,`im`,`titre`,`message`,`date_reception_technique`,`couleur_code`,`icone`,`type_key`,`nb_paliers_retard`) AS WITH RECURSIVE `progression_carriere` as (select `psa`.`im` AS `im`,`psa`.`statut_actuel` AS `statut_actuel`,`psa`.`categorie_actuel` AS `categorie_actuel`,`psa`.`type_acte_actuel` AS `type_acte_actuel`,`rc`.`id` AS `corps_id`,`rg`.`id` AS `grade_id_actuel`,`rg`.`libelle_grade` AS `grade_nom_actuel`,`rg`.`modele_id` AS `modele_id`,(case when ((`psa`.`statut_actuel` = 'Fonctionnaire') and (`psa`.`type_avancement_actuel` = 'Intégration') and (`psa`.`categorie_actuel` in ('IV','V','VI','VIII'))) then coalesce((select `pa`.`av_date_effet` from `personnel_avancements` `pa` where ((`pa`.`im` = `psa`.`im`) and (`pa`.`av_grade` = `psa`.`grade_actuel`)) order by `pa`.`id` desc limit 1),`psa`.`date_d_effet_actuel`) else `psa`.`date_d_effet_actuel` end) AS `date_effet_etape`,`rg`.`duree_annees` AS `duree_pour_prochain_palier`,1 AS `palier_niveau` from ((`personnel_situation_actuelle` `psa` join `ref_grades_types` `rg` on((`psa`.`grade_actuel` = `rg`.`libelle_grade`))) join `ref_corps` `rc` on(((`psa`.`corps_actuel` = `rc`.`libelle_corps`) and (`rc`.`modele_id` = `rg`.`modele_id`)))) where (((`psa`.`statut_actuel` = 'Contractuel EFA') and (left(`psa`.`code_corps_actuel`,1) = 'U')) or ((`psa`.`statut_actuel` = 'Fonctionnaire') and (left(`psa`.`code_corps_actuel`,1) in ('A','B','C')))) union all select `pc`.`im` AS `im`,`pc`.`statut_actuel` AS `statut_actuel`,`pc`.`categorie_actuel` AS `categorie_actuel`,`pc`.`type_acte_actuel` AS `type_acte_actuel`,`pc`.`corps_id` AS `corps_id`,`rg_next`.`id` AS `id`,`rg_next`.`libelle_grade` AS `libelle_grade`,`rg_next`.`modele_id` AS `modele_id`,(`pc`.`date_effet_etape` + interval (case when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'contrat')) then 1 when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'avenant')) then 2 else `pc`.`duree_pour_prochain_palier` end) year) AS `expr_1`,`rg_next`.`duree_annees` AS `duree_annees`,(`pc`.`palier_niveau` + 1) AS `pc.palier_niveau + 1` from (`progression_carriere` `pc` join `ref_grades_types` `rg_next` on(((`rg_next`.`modele_id` = `pc`.`modele_id`) and (`rg_next`.`id` = (`pc`.`grade_id_actuel` + 1))))) where ((`pc`.`date_effet_etape` + interval (case when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'contrat')) then 1 when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'avenant')) then 2 else `pc`.`duree_pour_prochain_palier` end) year) <= curdate())) select `alertes_finales`.`alerte_id` AS `alerte_id`,`alertes_finales`.`im` AS `im`,`alertes_finales`.`titre` AS `titre`,`alertes_finales`.`message` AS `message`,`alertes_finales`.`date_reception_technique` AS `date_reception_technique`,`alertes_finales`.`couleur_code` AS `couleur_code`,`alertes_finales`.`icone` AS `icone`,`alertes_finales`.`type_key` AS `type_key`,`alertes_finales`.`nb_paliers_retard` AS `nb_paliers_retard` from (select (concat(`pc`.`im`,'_AVANCEMENT_GROUPE') collate utf8mb4_0900_ai_ci) AS `alerte_id`,`pc`.`im` AS `im`,(concat(count(0),(case when (`pc`.`statut_actuel` = 'Contractuel EFA') then ' AVENANT(S) EN RETARD' else ' AVANCEMENT(S) EN RETARD' end)) collate utf8mb4_0900_ai_ci) AS `titre`,(concat((case when (count(0) > 1) then 'Vous êtes éligible aux avancements suivants : \n' else 'Vous êtes éligible à l\'avancement suivant : \n ' end),group_concat(concat('• ',`pc`.`grade_nom_actuel`,' (depuis le ',date_format(`pc`.`date_effet_etape`,'%d/%m/%Y'),')') separator '\n'),'\n Vous pouvez récupérer les pièces du dossier à constituer ici et passer au responsable de votre CISCO ou DREN pour finaliser la demande après.') collate utf8mb4_0900_ai_ci) AS `message`,min(`pc`.`date_effet_etape`) AS `date_reception_technique`,'sky' AS `couleur_code`,'fas fa-step-forward' AS `icone`,('ECHELON' collate utf8mb4_0900_ai_ci) AS `type_key`,count(0) AS `nb_paliers_retard` from `progression_carriere` `pc` where ((`pc`.`palier_niveau` > 1) and ((`pc`.`statut_actuel` <> 'Fonctionnaire') or (`pc`.`grade_nom_actuel` <> '2°CLASSE/1°ECHELON') or (`pc`.`palier_niveau` <> 2))) group by `pc`.`im`,`pc`.`statut_actuel` having (count(0) > 0) union all select (concat('HIDDEN_',`pc`.`im`,'_AVANCEMENT_',`pc`.`palier_niveau`) collate utf8mb4_0900_ai_ci) AS `expr_2`,`pc`.`im` AS `im`,`pc`.`grade_nom_actuel` AS `grade_nom_actuel`,`pc`.`grade_nom_actuel` AS `grade_nom_actuel`,`pc`.`date_effet_etape` AS `date_effet_etape`,'slate' AS `slate`,'fas fa-eye-slash' AS `fas fa-eye-slash`,'ECHELON_DETAIL' AS `ECHELON_DETAIL`,1 AS `1` from `progression_carriere` `pc` where ((`pc`.`palier_niveau` > 1) and ((`pc`.`statut_actuel` <> 'Fonctionnaire') or (`pc`.`grade_nom_actuel` <> '2°CLASSE/1°ECHELON') or (`pc`.`palier_niveau` <> 2))) union all select (concat(`personnel_situation_actuelle`.`im`,'_INTG') collate utf8mb4_0900_ai_ci) AS `expr_3`,`personnel_situation_actuelle`.`im` AS `im`,'Demande d\'Intégration' AS `Demande d'Intégration`,concat('Vous êtes éligible à l\'intégration depuis le ',date_format((`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year),'%d/%m/%Y'),', Veuillez passer au responsable du personnel encadré pour constituer votre dossier.') AS `expr_4`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year) AS `expr_5`,'purple' AS `purple`,'fas fa-fingerprint' AS `fas fa-fingerprint`,'INTG' AS `INTG`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) = 'U') and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year) <= curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_TITU') collate utf8mb4_0900_ai_ci) AS `expr_6`,`personnel_situation_actuelle`.`im` AS `im`,'Demande de Titularisation' AS `Demande de Titularisation`,concat('Vous êtes éligible à la titularisation depuis le ',date_format((`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year),'%d/%m/%Y'),', Veuillez passer au responsable du personnel encadré pour constituer votre dossier.') AS `expr_7`,(`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year) AS `expr_8`,'indigo' AS `indigo`,'fas fa-medal' AS `fas fa-medal`,'TITU' AS `TITU`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Fonctionnaire') and (`personnel_situation_actuelle`.`grade_actuel` = 'STAGIAIRE') and ((`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year) <= curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_RNC1') collate utf8mb4_0900_ai_ci) AS `expr_9`,`personnel_situation_actuelle`.`im` AS `im`,'Renouvellement du 1er contrat' AS `Renouvellement du 1er contrat`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day) <= curdate()) then concat('Votre 1er contrat a EXPIRÉ le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day),'%d/%m/%Y'),'. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') else concat('Votre 1er contrat finit le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day),'%d/%m/%Y'),'. Il vous reste ',(period_diff(extract(year_month from ((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day)),extract(year_month from curdate())) - if((dayofmonth(curdate()) > dayofmonth(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day))),1,0)),' mois et ',((to_days(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day)) - to_days(curdate())) % 30),' jours. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') end) AS `message`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 12 month) AS `date_reception_technique`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day) <= curdate()) then 'red' else 'orange' end) AS `expr_10`,'fas fa-file-contract' AS `fas fa-file-contract`,'CONTRAT' AS `CONTRAT`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) in ('L','K','J')) and (`personnel_situation_actuelle`.`date_d_effet_actuel` < (`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month)) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 12 month) <= curdate()) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) > curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_RNC2') collate utf8mb4_0900_ai_ci) AS `expr_11`,`personnel_situation_actuelle`.`im` AS `im`,'Renouvellement du 2ème contrat' AS `Renouvellement du 2ème contrat`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day) <= curdate()) then concat('Votre 2ème contrat a EXPIRÉ le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day),'%d/%m/%Y'),'. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') else concat('Votre 2ème contrat finit le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day),'%d/%m/%Y'),'. Il vous reste ',(period_diff(extract(year_month from ((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day)),extract(year_month from curdate())) - if((dayofmonth(curdate()) > dayofmonth(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day))),1,0)),' mois et ',((to_days(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day)) - to_days(curdate())) % 30),' jours. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') end) AS `message`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) AS `date_reception_technique`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day) <= curdate()) then 'red' else 'orange' end) AS `expr_12`,'fas fa-file-contract' AS `fas fa-file-contract`,'CONTRAT' AS `CONTRAT`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) in ('L','K','J')) and (`personnel_situation_actuelle`.`date_d_effet_actuel` < (`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month)) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) <= curdate())) union all select (concat(`personnel_etat_civil`.`im`,'_RETRAITE') collate utf8mb4_0900_ai_ci) AS `expr_13`,`personnel_etat_civil`.`im` AS `im`,'Demande d\'arrêté d\'admission à la retraite' AS `Demande d'arrêté d'admission à la retraite`,(case when ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= curdate()) then concat('Vous avez atteint l\'âge de la retraite le ',date_format((`personnel_etat_civil`.`date_naiss` + interval 60 year),'%d/%m/%Y'),'. Si ce n\'est pas encore fait, vous devez demander d\'urgence votre arrêté d\'admission à la retraite.') else concat('Vous atteindrez l\'âge de la retraite le ',date_format((`personnel_etat_civil`.`date_naiss` + interval 60 year),'%d/%m/%Y'),'. Il est temps de faire la demande de votre arrêté d\'admission à la retraite dès aujourd\'hui.') end) AS `message`,((`personnel_etat_civil`.`date_naiss` + interval 60 year) - interval 1 year) AS `date_reception_technique`,(case when ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= curdate()) then 'red' else 'orange' end) AS `expr_14`,'fas fa-user-clock' AS `fas fa-user-clock`,'RETRAITE' AS `RETRAITE`,1 AS `1` from `personnel_etat_civil` where ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= (curdate() + interval 1 year)) union all select (concat(`u`.`im`,'_BORD_DREN_',`b`.`id`) collate utf8mb4_0900_ai_ci) AS `id`,`u`.`im` AS `im`,'Bordereau en attente de traitement' AS `titre`,concat('Le bordereau n° ',`b`.`numero_complet`,' du ',date_format(`b`.`date_envoi_bordereau`,'%d/%m/%Y'),', transmis par le ',(case when (`b`.`type_etablissement` = 'CISCO') then concat('CISCO ',coalesce(`b`.`expediteur`,'')) when (`b`.`type_etablissement` = 'CRFRP') then coalesce(`b`.`expediteur`,'') else coalesce(`b`.`expediteur`,'') end),', contient ',((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1),if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),' dossiers d’agents relatifs à une demande de création de projet ',' dossier d’agent relatif à une demande de création de projet '),(case `b`.`type_demande` when 'renouvellement' then 'de renouvellement de contrat' when 'avenant' then 'd\'avenant' when 'avancement_classe' then 'd\'avancement de classe et d\'echelon' when 'avancement_echelon' then 'd\'avancement d\'echelon' when 'integration' then 'd\'intégration' when 'titularisation' then 'de titularisation' when 'admission_retraite' then 'd\'admission à la retraite' else coalesce(`b`.`type_demande`,'') end),'. Veuillez : \n • accéder au menu « Référence des dossiers » pour attribuer une référence au bordereau, \n • puis accéder au menu « Traitement des dossiers » afin de traiter ',if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),'les dossiers des agents concernés.','le dossier de l’agent concerné.')) AS `message`,`b`.`date_envoi_bordereau` AS `date_reception_technique`,'orange' AS `couleur`,'fas fa-folder-open' AS `icone`,'BORDEREAU' AS `categorie`,1 AS `statut` from (((((`archives_bordereaux_dren` `b` left join `ref_crfrp` `c` on(((`b`.`type_etablissement` = 'CRFRP') and (`c`.`nom_crfrp` = `b`.`expediteur`)))) left join `ref_districts` `d_crfrp` on(((`b`.`type_etablissement` = 'CRFRP') and (`d_crfrp`.`id` = `c`.`district_id`)))) left join `ref_districts` `d_cisco` on(((`b`.`type_etablissement` = 'CISCO') and (`d_cisco`.`nom_district` = `b`.`expediteur`)))) left join `ref_regions` `r` on((`r`.`id` = coalesce(`d_crfrp`.`region_id`,`d_cisco`.`region_id`)))) join `utilisateurs` `u` on(((`u`.`niveau` = 'regional') and (lower(`u`.`code_lieu_affectation`) = lower(`r`.`nom_region`)) and (`u`.`role_specifique` = (case when (`b`.`type_demande` in ('renouvellement','avenant','integration')) then 'resp_non_encadre' when (`b`.`type_demande` in ('titularisation','avancement_echelon','avancement_classe','admission_retraite')) then 'resp_encadre' else NULL end))))) where (`b`.`statut_bordereau` = 'en_attente') union all select (concat(`u`.`im`,'_BORD_DRH_',`b`.`id`) collate utf8mb4_0900_ai_ci) AS `id`,`u`.`im` AS `im`,'Bordereau en attente de traitement (DRH)' AS `titre`,concat('Le bordereau n° ',`b`.`numero_complet`,' du ',date_format(`b`.`date_envoi_bordereau`,'%d/%m/%Y'),', transmis par la DREN ',coalesce(`b`.`expediteur`,'DREN'),', contient ',((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_ag