rte`,'green' AS `couleur`,'fas fa-check-double' AS `icone`,'SORTIE' AS `type_alerte`,1 AS `est_actif` from (`suivi_agents_bordereau` `s` left join `personnel_situation_actuelle` `psa` on((`s`.`im_agent` = `psa`.`im`))) where ((`s`.`statut_finale` = 'valide') and ((`s`.`est_notifie` = 0) or (`s`.`est_notifie` is null))) union all select (concat(`a`.`im`,'_STEP_MANDATEMENT_',`a`.`id`) collate utf8mb4_0900_ai_ci) AS `alerte_id`,`a`.`im` AS `im`,'Dépôt de mandatement à la Solde et Pensions' AS `titre`,concat('Votre mandatement de la demande ',(case when (`a`.`type_demande` = 'renouvellement') then 'de renouvellement de contrat' when (`a`.`type_demande` = 'avenant') then 'd\'avenant' when (`a`.`type_demande` = 'avancement_classe') then 'd\'avancement de classe et d\'échelon' when (`a`.`type_demande` = 'avancement_echelon') then 'd\'avancement d\'échelon' when (`a`.`type_demande` = 'integration') then 'd\'intégration' when (`a`.`type_demande` = 'titularisation') then 'de titularisation' else coalesce(`a`.`type_demande`,'administrative') end),' est déposé au service solde et pensions :  \n - Bordereau N°',`a`.`bordereaux_mandatement`,', \n - Référence N°',`a`.`ref_mandatement`,' du ',date_format(`a`.`date_reference_bordereau`,'%d/%m/%Y'),'.') AS `message`,now() AS `date_reception_technique`,'teal' AS `couleur_code`,'fas fa-file-invoice-dollar' AS `icone`,'DOS_STEP' AS `type_key`,1 AS `nb_paliers_retard` from ((`acte_formate` `a` left join `personnel_situation_actuelle` `psa` on((`a`.`im` = `psa`.`im`))) left join `personnel_etat_civil` `pec` on((`a`.`im` = `pec`.`im`))) where ((`a`.`ref_mandatement` is not null) and (`a`.`ref_mandatement` <> '') and (`a`.`bordereaux_mandatement` is not null) and (`a`.`bordereaux_mandatement` <> '') and exists(select 1 from `progression_carriere` `pc_chk` where ((`pc_chk`.`im` = `a`.`im`) and (`pc_chk`.`palier_niveau` > 1))) is false and ((`psa`.`statut_actuel` <> 'Contractuel EFA') or (left(`psa`.`code_corps_actuel`,1) not in ('L','K','J')) or (`psa`.`date_d_effet_actuel` >= (`psa`.`date_entree_admin` + interval 24 month)) or ((`psa`.`date_entree_admin` + interval 12 month) > curdate()) or ((`psa`.`date_entree_admin` + interval 36 month) <= curdate())) and ((`psa`.`statut_actuel` <> 'Contractuel EFA') or (left(`psa`.`code_corps_actuel`,1) not in ('L','K','J')) or (`psa`.`date_d_effet_actuel` >= (`psa`.`date_entree_admin` + interval 48 month)) or ((`psa`.`date_entree_admin` + interval 36 month) > curdate())) and ((`psa`.`statut_actuel` <> 'Contractuel EFA') or (left(`psa`.`code_corps_actuel`,1) <> 'U') or ((`psa`.`date_entree_admin` + interval 6 year) > curdate())) and ((`psa`.`statut_actuel` <> 'Fonctionnaire') or (`psa`.`grade_actuel` <> 'STAGIAIRE') or ((`psa`.`date_d_effet_actuel` + interval 1 year) > curdate())) and ((`pec`.`date_naiss` is null) or ((`pec`.`date_naiss` + interval 60 year) > (curdate() + interval 1 year))))) `alertes_finales`  ;
